import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Compare per project
for bp, ap in zip(baseline['projects'], after['projects']):
    proj = bp['path'].split('/')[-2]
    for bf, af in zip(bp['frameworks'], ap['frameworks']):
        tfm = bf['framework']
        b_pkgs = {p['id']: p['resolvedVersion'] for p in bf['topLevelPackages']}
        a_pkgs = {p['id']: p['resolvedVersion'] for p in af['topLevelPackages']}
        for pkg in sorted(set(list(b_pkgs.keys()) + list(a_pkgs.keys()))):
            bv = b_pkgs.get(pkg, 'MISSING')
            av = a_pkgs.get(pkg, 'MISSING')
            if bv != av:
                print(f'CHANGED: {proj}/{tfm} {pkg}: {bv} -> {av}')
print('Comparison complete.')
"

